            rule_section(:moves, "Ruchy pion\u00F3w",
              "Zwyk\u0142y pion przesuwa si\u0119 o jedno pole po przek\u0105tnej do przodu, je\u015Bli to pole jest puste. Przejd\u017A do piona strza\u0142kami i wybierz go Enterem. Potem wska\u017C pole docelowe i jeszcze raz naci\u015Bnij Enter. Stoj\u0105c na polu z pionem lub damk\u0105, mo\u017Cesz nacisn\u0105\u0107 V, \u017Ceby sprawdzi\u0107 mo\u017Cliwe ruchy.",
              "Gdy pion zako\u0144czy sw\u00F3j ruch w ostatnim rz\u0119dzie po stronie przeciwnika, zostaje damk\u0105. Damka ma wi\u0119kszy zasi\u0119g: mo\u017Ce przej\u015B\u0107 o dowoln\u0105 liczb\u0119 pustych p\u00F3l po przek\u0105tnej, do przodu lub do ty\u0142u."),
            rule_section(:captures, "Bicie",
              "Je\u015Bli po przek\u0105tnej stoi s\u0105siedni pion albo damka przeciwnika, a tu\u017C za nim jest puste pole, mo\u017Cesz go przeskoczy\u0107 i zbi\u0107. Pion bije zar\u00F3wno do przodu, jak i do ty\u0142u. Wybierasz pion Enterem, a drugim Enterem zatwierdzasz puste pole za zbijan\u0105 bierk\u0105.",
              "Bicie jest obowi\u0105zkowe. Gdy masz kilka mo\u017Cliwo\u015Bci, musisz wybra\u0107 tak\u0105 seri\u0119 skok\u00F3w, kt\u00F3ra pozwoli zbi\u0107 najwi\u0119cej bierek. Je\u015Bli kilka serii daje ten sam wynik, mo\u017Cesz wybra\u0107 dowoln\u0105 z nich.",
              "Po skoku sprawdzasz, czy tym samym pionem lub damk\u0105 da si\u0119 bi\u0107 dalej. Je\u015Bli tak, musisz kontynuowa\u0107. Wybierz ponownie poruszany pion Enterem i wska\u017C kolejne pole l\u0105dowania. W ten spos\u00F3b wykonujesz ka\u017Cdy skok, a\u017C seria si\u0119 sko\u0144czy.",
              "Damka mo\u017Ce doj\u015B\u0107 po przek\u0105tnej do odleg\u0142ej bierki przeciwnika i przeskoczy\u0107 j\u0105. L\u0105duje na dowolnym wolnym polu za ni\u0105, dop\u00F3ki nie napotka nast\u0119pnej bierki. Ka\u017Cdy skok zbija tylko jedn\u0105 bierk\u0119.",
              "Zbite piony i damki znikaj\u0105 dopiero po zako\u0144czeniu ca\u0142ej serii. Do tego czasu zajmuj\u0105 pola i blokuj\u0105 drog\u0119; nie mo\u017Cna ich przeskoczy\u0107 po raz drugi.",
              "Pion staje si\u0119 damk\u0105 dopiero na ko\u0144cu ca\u0142ego ruchu. Je\u015Bli w trakcie serii dotrze do ostatniego rz\u0119du, lecz kolejne bicie wyprowadzi go z tego rz\u0119du, pozostanie pionem."),
            rule_section(:ending, "Zako\u0144czenie partii",
              "Wygrywasz, gdy przeciwnik straci wszystkie bierki lub nie b\u0119dzie mia\u0142 \u017Cadnego dozwolonego ruchu.",
              "Partia ko\u0144czy si\u0119 remisem po trzykrotnym powt\u00F3rzeniu pozycji albo po osiemdziesi\u0119ciu kolejnych turach bez bicia i bez przemiany piona w damk\u0119. Ca\u0142a seria skok\u00F3w liczy si\u0119 jako jedna tura."),
            rule_section(:board_variant, "Wi\u0119ksze plansze",
              "W ustawieniach przed gr\u0105 mo\u017Cna wybra\u0107 wi\u0119ksz\u0105 plansz\u0119. Dost\u0119pne s\u0105 trzy rozmiary:",
              "- Na planszy 8 na 8 ka\u017Cdy gracz ma dwana\u015Bcie pion\u00F3w. To zwyk\u0142e ustawienie.",
              "- Na planszy 10 na 10 ka\u017Cdy zaczyna z dwudziestoma pionami.",
              "- Na planszy 12 na 12 ka\u017Cdy zaczyna z trzydziestoma pionami.",
              "Na ka\u017Cdej z tych plansz piony przeciwnik\u00F3w rozdzielaj\u0105 na pocz\u0105tku dwa puste rz\u0119dy."),
            rule_section(:rule_variants, "Zmiany zasad ruchu i bicia",
              "W ustawieniach przed gr\u0105 mo\u017Cna osobno zmienia\u0107 zasady ruchu i bicia. Wielko\u015B\u0107 planszy sama w sobie nie w\u0142\u0105cza \u017Cadnej z tych zmian.",
              "- Wy\u0142\u0105czenie bicia pionem do ty\u0142u zostawia mu tylko bicie do przodu.",
              "- Wy\u0142\u0105czenie dalekiego ruchu damki ogranicza jej zwyk\u0142y ruch do jednego pola po przek\u0105tnej, a bicie do skoku nad bezpo\u015Brednim s\u0105siadem.",
              "- Po wy\u0142\u0105czeniu obowi\u0105zku bicia mo\u017Cesz wykona\u0107 zwyk\u0142y ruch, cho\u0107 masz okazj\u0119 zbi\u0107 przeciwnika.",
              "- Po wy\u0142\u0105czeniu dalszych bi\u0107 tura ko\u0144czy si\u0119 ju\u017C po pierwszym skoku.",
              "- Po wy\u0142\u0105czeniu obowi\u0105zku najd\u0142u\u017Cszego bicia wybierasz dowoln\u0105 dopuszczaln\u0105 seri\u0119. Obowi\u0105zek najd\u0142u\u017Cszego bicia mo\u017Cna stosowa\u0107 tylko razem z obowi\u0105zkowym biciem i kontynuowaniem serii.",
              "- Mo\u017Cna pozwoli\u0107 zwyk\u0142ym pionom na ruch o jedno puste pole po przek\u0105tnej do ty\u0142u. W normalnej grze piony mog\u0105 cofa\u0107 si\u0119 tylko przy biciu.",
              "- Pierwsze\u0144stwo damki rozstrzyga wyb\u00F3r mi\u0119dzy r\u00F3wnie d\u0142ugimi seriami: je\u015Bli jedn\u0105 z nich mo\u017Ce wykona\u0107 damka, trzeba u\u017Cy\u0107 damki. Ta zasada wymaga w\u0142\u0105czenia najd\u0142u\u017Cszego bicia; zwykle jest wy\u0142\u0105czona.",
              "- Mo\u017Cna w\u0142\u0105czy\u0107 natychmiastow\u0105 przemian\u0119 podczas bicia. Pion, kt\u00F3ry dotrze do ostatniego rz\u0119du, staje si\u0119 wtedy damk\u0105 i dalsze skoki wykonuje ju\u017C jako damka.",
              "- Po wy\u0142\u0105czeniu pozostawiania zbitych bierek na planszy ka\u017Cda znika od razu po skoku. Mo\u017Ce to otworzy\u0107 drog\u0119 do kolejnego bicia w tej samej serii."),
            rule_section(:controls, "Skr\u00F3ty klawiszowe",
              "Strza\u0142ki: przegl\u0105daj pola planszy.",
              "Enter: wybierz pion lub damk\u0119, a nast\u0119pnie cel ruchu; w serii bi\u0107 zatwierdzaj ka\u017Cdy skok osobno.",
              "V: odczytaj mo\u017Cliwe ruchy ogl\u0105danej figury.",
              "K: przejd\u017A do kolejnej swojej damki.",
              "Shift+K: przejd\u017A do kolejnej damki przeciwnika.",
              "C: odczytaj kolory graczy.",
              "S: odczytaj pozosta\u0142e piony i damki obu graczy.",
              "Ctrl+H: prze\u0142\u0105cz numery p\u00F3l i wsp\u00F3\u0142rz\u0119dne szachowe.",
              "Ctrl+Shift+H: obr\u00F3\u0107 widok planszy.",
              "T: odczytaj, czyja jest tura.")
          ]
        when "ru"
          [
            rule_section(:aim, "\u0426\u0435\u043B\u044C \u0438\u0433\u0440\u044B",
              "\u0412 \u0448\u0430\u0448\u043A\u0430\u0445 \u043D\u0443\u0436\u043D\u043E \u0432\u0437\u044F\u0442\u044C \u0432\u0441\u0435 \u0448\u0430\u0448\u043A\u0438 \u0438 \u0434\u0430\u043C\u043A\u0438 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430 \u0438\u043B\u0438 \u043B\u0438\u0448\u0438\u0442\u044C \u0435\u0433\u043E \u0432\u043E\u0437\u043C\u043E\u0436\u043D\u043E\u0441\u0442\u0438 \u0445\u043E\u0434\u0438\u0442\u044C. \u0418\u0433\u0440\u0430\u044E\u0442 \u0432\u0434\u0432\u043E\u0451\u043C, \u043F\u0435\u0440\u0432\u044B\u0439 \u0445\u043E\u0434 \u0434\u0435\u043B\u0430\u044E\u0442 \u0431\u0435\u043B\u044B\u0435.",
              "\u041F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0435\u0442\u0441\u044F \u0434\u043E\u0441\u043A\u0430 8 \u043D\u0430 8 \u043A\u043B\u0435\u0442\u043E\u043A. \u0423 \u043A\u0430\u0436\u0434\u043E\u0433\u043E \u0438\u0433\u0440\u043E\u043A\u0430 \u043F\u043E \u0434\u0432\u0435\u043D\u0430\u0434\u0446\u0430\u0442\u044C \u043F\u0440\u043E\u0441\u0442\u044B\u0445 \u0448\u0430\u0448\u0435\u043A; \u0445\u043E\u0434\u044F\u0442 \u0442\u043E\u043B\u044C\u043A\u043E \u043F\u043E \u0442\u0451\u043C\u043D\u044B\u043C \u043A\u043B\u0435\u0442\u043A\u0430\u043C."),
            rule_section(:moves, "\u0425\u043E\u0434\u044B \u0448\u0430\u0448\u0435\u043A \u0438 \u0434\u0430\u043C\u043E\u043A",
              "\u041F\u0440\u043E\u0441\u0442\u0430\u044F \u0448\u0430\u0448\u043A\u0430 \u0445\u043E\u0434\u0438\u0442 \u043D\u0430 \u043E\u0434\u043D\u0443 \u0441\u0432\u043E\u0431\u043E\u0434\u043D\u0443\u044E \u043A\u043B\u0435\u0442\u043A\u0443 \u0432\u043F\u0435\u0440\u0451\u0434 \u043F\u043E \u0434\u0438\u0430\u0433\u043E\u043D\u0430\u043B\u0438. \u041D\u0430\u0439\u0434\u0438\u0442\u0435 \u0441\u0432\u043E\u044E \u0448\u0430\u0448\u043A\u0443 \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u0438 \u043D\u0430\u0436\u043C\u0438\u0442\u0435 Enter, \u0437\u0430\u0442\u0435\u043C \u043F\u0435\u0440\u0435\u0439\u0434\u0438\u0442\u0435 \u043D\u0430 \u043D\u0443\u0436\u043D\u0443\u044E \u043A\u043B\u0435\u0442\u043A\u0443 \u0438 \u0441\u043D\u043E\u0432\u0430 \u043D\u0430\u0436\u043C\u0438\u0442\u0435 Enter. \u041A\u043B\u0430\u0432\u0438\u0448\u0430 V \u043D\u0430 \u043A\u043B\u0435\u0442\u043A\u0435 \u0441 \u0448\u0430\u0448\u043A\u043E\u0439 \u0438\u043B\u0438 \u0434\u0430\u043C\u043A\u043E\u0439 \u043F\u0435\u0440\u0435\u0447\u0438\u0441\u043B\u044F\u0435\u0442 \u0435\u0451 \u0434\u043E\u043F\u0443\u0441\u0442\u0438\u043C\u044B\u0435 \u0445\u043E\u0434\u044B.",
              "\u0428\u0430\u0448\u043A\u0430, \u0437\u0430\u043A\u043E\u043D\u0447\u0438\u0432\u0448\u0430\u044F \u0445\u043E\u0434 \u043D\u0430 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0435\u043C \u0440\u044F\u0434\u0443 \u0441\u043E \u0441\u0442\u043E\u0440\u043E\u043D\u044B \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430, \u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u0441\u044F \u0434\u0430\u043C\u043A\u043E\u0439. \u0414\u0430\u043C\u043A\u0430 \u0445\u043E\u0434\u0438\u0442 \u043F\u043E \u0434\u0438\u0430\u0433\u043E\u043D\u0430\u043B\u0438 \u043D\u0430 \u043B\u044E\u0431\u043E\u0435 \u0447\u0438\u0441\u043B\u043E \u0441\u0432\u043E\u0431\u043E\u0434\u043D\u044B\u0445 \u043A\u043B\u0435\u0442\u043E\u043A \u043A\u0430\u043A \u0432\u043F\u0435\u0440\u0451\u0434, \u0442\u0430\u043A \u0438 \u043D\u0430\u0437\u0430\u0434."),
            rule_section(:captures, "\u0412\u0437\u044F\u0442\u0438\u0435",
              "\u0415\u0441\u043B\u0438 \u043D\u0430 \u0441\u043E\u0441\u0435\u0434\u043D\u0435\u0439 \u043F\u043E \u0434\u0438\u0430\u0433\u043E\u043D\u0430\u043B\u0438 \u043A\u043B\u0435\u0442\u043A\u0435 \u0441\u0442\u043E\u0438\u0442 \u0447\u0443\u0436\u0430\u044F \u0448\u0430\u0448\u043A\u0430 \u0438\u043B\u0438 \u0434\u0430\u043C\u043A\u0430, \u0430 \u0441\u0440\u0430\u0437\u0443 \u0437\u0430 \u043D\u0435\u0439 \u0441\u0432\u043E\u0431\u043E\u0434\u043D\u043E, \u043C\u043E\u0436\u043D\u043E \u043F\u0435\u0440\u0435\u043F\u0440\u044B\u0433\u043D\u0443\u0442\u044C \u0447\u0435\u0440\u0435\u0437 \u043D\u0435\u0451 \u0438 \u0432\u0437\u044F\u0442\u044C. \u041F\u0440\u043E\u0441\u0442\u0430\u044F \u0448\u0430\u0448\u043A\u0430 \u0431\u044C\u0451\u0442 \u0438 \u0432\u043F\u0435\u0440\u0451\u0434, \u0438 \u043D\u0430\u0437\u0430\u0434. \u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0435\u0451 \u043A\u043B\u0430\u0432\u0438\u0448\u0435\u0439 Enter, \u0437\u0430\u0442\u0435\u043C \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0435 Enter \u0441\u0432\u043E\u0431\u043E\u0434\u043D\u0443\u044E \u043A\u043B\u0435\u0442\u043A\u0443 \u0437\u0430 \u0448\u0430\u0448\u043A\u043E\u0439 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430.",
              "\u0412\u0437\u044F\u0442\u0438\u0435 \u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u043E. \u0415\u0441\u043B\u0438 \u0435\u0441\u0442\u044C \u043D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u043E \u043F\u0443\u0442\u0435\u0439, \u043D\u0443\u0436\u043D\u043E \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u0442\u043E\u0442, \u043D\u0430 \u043A\u043E\u0442\u043E\u0440\u043E\u043C \u0437\u0430 \u043E\u0434\u0438\u043D \u0445\u043E\u0434 \u0443\u0434\u0430\u0441\u0442\u0441\u044F \u0432\u0437\u044F\u0442\u044C \u0431\u043E\u043B\u044C\u0448\u0435 \u0432\u0441\u0435\u0433\u043E \u0448\u0430\u0448\u0435\u043A. \u041F\u0440\u0438 \u0440\u0430\u0432\u043D\u043E\u0439 \u0434\u043B\u0438\u043D\u0435 \u0442\u0430\u043A\u0438\u0445 \u043F\u0443\u0442\u0435\u0439 \u0432\u044B\u0431\u0438\u0440\u0430\u0439\u0442\u0435 \u043B\u044E\u0431\u043E\u0439.",
              "\u041F\u043E\u0441\u043B\u0435 \u043F\u0440\u044B\u0436\u043A\u0430 \u043D\u0443\u0436\u043D\u043E \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0438\u0442\u044C \u0432\u0437\u044F\u0442\u0438\u0435 \u0442\u043E\u0439 \u0436\u0435 \u0448\u0430\u0448\u043A\u043E\u0439 \u0438\u043B\u0438 \u0434\u0430\u043C\u043A\u043E\u0439, \u0435\u0441\u043B\u0438 \u044D\u0442\u043E \u0432\u043E\u0437\u043C\u043E\u0436\u043D\u043E. \u0415\u0449\u0451 \u0440\u0430\u0437 \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0435\u0451 \u043A\u043B\u0430\u0432\u0438\u0448\u0435\u0439 Enter \u0438 \u0443\u043A\u0430\u0436\u0438\u0442\u0435 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0443\u044E \u043A\u043B\u0435\u0442\u043A\u0443 \u043F\u0440\u0438\u0437\u0435\u043C\u043B\u0435\u043D\u0438\u044F. \u0422\u0430\u043A \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u0435\u0442\u0441\u044F \u043A\u0430\u0436\u0434\u044B\u0439 \u043F\u0440\u044B\u0436\u043E\u043A \u0434\u043E \u043A\u043E\u043D\u0446\u0430 \u0432\u0441\u0435\u0439 \u0446\u0435\u043F\u043E\u0447\u043A\u0438.",
              "\u0414\u0430\u043C\u043A\u0430 \u043C\u043E\u0436\u0435\u0442 \u043F\u043E\u0434\u043E\u0439\u0442\u0438 \u043F\u043E \u0434\u0438\u0430\u0433\u043E\u043D\u0430\u043B\u0438 \u043A \u0443\u0434\u0430\u043B\u0451\u043D\u043D\u043E\u0439 \u0448\u0430\u0448\u043A\u0435 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430 \u0438 \u043F\u0435\u0440\u0435\u043F\u0440\u044B\u0433\u043D\u0443\u0442\u044C \u0447\u0435\u0440\u0435\u0437 \u043D\u0435\u0451. \u041F\u0440\u0438\u0437\u0435\u043C\u043B\u0438\u0442\u044C\u0441\u044F \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043D\u043E \u043D\u0430 \u043B\u044E\u0431\u0443\u044E \u0441\u0432\u043E\u0431\u043E\u0434\u043D\u0443\u044E \u043A\u043B\u0435\u0442\u043A\u0443 \u0437\u0430 \u0432\u0437\u044F\u0442\u043E\u0439 \u0448\u0430\u0448\u043A\u043E\u0439 \u0434\u043E \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0439 \u043F\u0440\u0435\u0433\u0440\u0430\u0434\u044B. \u0417\u0430 \u043E\u0434\u0438\u043D \u043F\u0440\u044B\u0436\u043E\u043A \u0431\u0435\u0440\u0451\u0442\u0441\u044F \u0442\u043E\u043B\u044C\u043A\u043E \u043E\u0434\u043D\u0430 \u0448\u0430\u0448\u043A\u0430.",
              "\u0412\u0437\u044F\u0442\u044B\u0435 \u0448\u0430\u0448\u043A\u0438 \u0438 \u0434\u0430\u043C\u043A\u0438 \u0441\u043D\u0438\u043C\u0430\u044E\u0442\u0441\u044F \u0441 \u0434\u043E\u0441\u043A\u0438 \u043B\u0438\u0448\u044C \u043F\u043E\u0441\u043B\u0435 \u0432\u0441\u0435\u0433\u043E \u0445\u043E\u0434\u0430. \u041F\u043E\u043A\u0430 \u0438\u0434\u0451\u0442 \u0446\u0435\u043F\u043E\u0447\u043A\u0430 \u0432\u0437\u044F\u0442\u0438\u0439, \u043E\u043D\u0438 \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0430\u044E\u0442 \u0437\u0430\u043D\u0438\u043C\u0430\u0442\u044C \u0441\u0432\u043E\u0438 \u043A\u043B\u0435\u0442\u043A\u0438 \u0438 \u043F\u0440\u0435\u0433\u0440\u0430\u0436\u0434\u0430\u0442\u044C \u043F\u0443\u0442\u044C; \u043F\u0435\u0440\u0435\u0441\u043A\u0430\u043A\u0438\u0432\u0430\u0442\u044C \u0438\u0445 \u0432\u0442\u043E\u0440\u043E\u0439 \u0440\u0430\u0437 \u043D\u0435\u043B\u044C\u0437\u044F.",
              "\u041F\u0440\u0435\u0432\u0440\u0430\u0449\u0435\u043D\u0438\u0435 \u0432 \u0434\u0430\u043C\u043A\u0443 \u0442\u043E\u0436\u0435 \u043F\u0440\u043E\u0438\u0441\u0445\u043E\u0434\u0438\u0442 \u0442\u043E\u043B\u044C\u043A\u043E \u0432 \u043A\u043E\u043D\u0446\u0435 \u0445\u043E\u0434\u0430. \u0415\u0441\u043B\u0438 \u043F\u0440\u043E\u0441\u0442\u0430\u044F \u0448\u0430\u0448\u043A\u0430 \u0432\u043E \u0432\u0440\u0435\u043C\u044F \u0432\u0437\u044F\u0442\u0438\u044F \u0434\u043E\u0441\u0442\u0438\u0433\u043B\u0430 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0435\u0433\u043E \u0440\u044F\u0434\u0430, \u043D\u043E \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u043C \u043F\u0440\u044B\u0436\u043A\u043E\u043C \u0443\u0448\u043B\u0430 \u0441 \u043D\u0435\u0433\u043E, \u043E\u043D\u0430 \u043E\u0441\u0442\u0430\u0451\u0442\u0441\u044F \u043F\u0440\u043E\u0441\u0442\u043E\u0439."),
            rule_section(:ending, "\u041F\u043E\u0431\u0435\u0434\u0430 \u0438 \u043D\u0438\u0447\u044C\u044F",
              "\u0412\u044B \u043F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442\u0435, \u043A\u043E\u0433\u0434\u0430 \u0443 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430 \u043D\u0435 \u043E\u0441\u0442\u0430\u043B\u043E\u0441\u044C \u0448\u0430\u0448\u0435\u043A \u0438 \u0434\u0430\u043C\u043E\u043A \u0438\u043B\u0438 \u043E\u043D \u043D\u0435 \u043C\u043E\u0436\u0435\u0442 \u0441\u0434\u0435\u043B\u0430\u0442\u044C \u043D\u0438 \u043E\u0434\u043D\u043E\u0433\u043E \u0434\u043E\u043F\u0443\u0441\u0442\u0438\u043C\u043E\u0433\u043E \u0445\u043E\u0434\u0430.",
              "\u041D\u0438\u0447\u044C\u044F \u043D\u0430\u0441\u0442\u0443\u043F\u0430\u0435\u0442 \u043F\u0440\u0438 \u0442\u0440\u0435\u0442\u044C\u0435\u043C \u043F\u043E\u0432\u0442\u043E\u0440\u0435\u043D\u0438\u0438 \u043F\u043E\u0437\u0438\u0446\u0438\u0438 \u0438\u043B\u0438 \u043F\u043E\u0441\u043B\u0435 \u0432\u043E\u0441\u044C\u043C\u0438\u0434\u0435\u0441\u044F\u0442\u0438 \u0445\u043E\u0434\u043E\u0432 \u043F\u043E\u0434\u0440\u044F\u0434 \u0431\u0435\u0437 \u0432\u0437\u044F\u0442\u0438\u044F \u0438 \u043F\u0440\u0435\u0432\u0440\u0430\u0449\u0435\u043D\u0438\u044F \u0432 \u0434\u0430\u043C\u043A\u0443. \u0412\u0441\u044F \u0446\u0435\u043F\u043E\u0447\u043A\u0430 \u043F\u0440\u044B\u0436\u043A\u043E\u0432 \u0441\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044F \u043E\u0434\u043D\u0438\u043C \u0445\u043E\u0434\u043E\u043C."),
            rule_section(:board_variant, "\u0420\u0430\u0437\u043C\u0435\u0440 \u0434\u043E\u0441\u043A\u0438",
              "\u0414\u043E \u043D\u0430\u0447\u0430\u043B\u0430 \u0438\u0433\u0440\u044B \u043C\u043E\u0436\u043D\u043E \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u0440\u0430\u0437\u043C\u0435\u0440 \u0434\u043E\u0441\u043A\u0438:",
              "- 8 \u043D\u0430 8: \u043F\u043E \u0434\u0432\u0435\u043D\u0430\u0434\u0446\u0430\u0442\u044C \u0448\u0430\u0448\u0435\u043A, \u043E\u0431\u044B\u0447\u043D\u043E\u0435 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0435.",
              "- 10 \u043D\u0430 10: \u043F\u043E \u0434\u0432\u0430\u0434\u0446\u0430\u0442\u044C \u0448\u0430\u0448\u0435\u043A.",
              "- 12 \u043D\u0430 12: \u043F\u043E \u0442\u0440\u0438\u0434\u0446\u0430\u0442\u044C \u0448\u0430\u0448\u0435\u043A.",
              "\u041F\u0440\u0438 \u043B\u044E\u0431\u043E\u043C \u0440\u0430\u0437\u043C\u0435\u0440\u0435 \u0432 \u043D\u0430\u0447\u0430\u043B\u044C\u043D\u043E\u0439 \u0440\u0430\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0435 \u043C\u0435\u0436\u0434\u0443 \u0441\u0442\u043E\u0440\u043E\u043D\u0430\u043C\u0438 \u043E\u0441\u0442\u0430\u044E\u0442\u0441\u044F \u0434\u0432\u0430 \u043F\u0443\u0441\u0442\u044B\u0445 \u0440\u044F\u0434\u0430."),
            rule_section(:rule_variants, "\u0412\u0430\u0440\u0438\u0430\u043D\u0442\u044B \u0445\u043E\u0434\u043E\u0432 \u0438 \u0432\u0437\u044F\u0442\u0438\u0439",
              "\u041F\u0440\u0430\u0432\u0438\u043B\u0430 \u0434\u0432\u0438\u0436\u0435\u043D\u0438\u044F \u0438 \u0432\u0437\u044F\u0442\u0438\u044F \u043C\u0435\u043D\u044F\u044E\u0442\u0441\u044F \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u043E \u0432 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u0445 \u043F\u0435\u0440\u0435\u0434 \u043F\u0430\u0440\u0442\u0438\u0435\u0439. \u0412\u044B\u0431\u043E\u0440 \u0431\u043E\u043B\u044C\u0448\u043E\u0439 \u0434\u043E\u0441\u043A\u0438 \u0441\u0430\u043C \u043F\u043E \u0441\u0435\u0431\u0435 \u0438\u0445 \u043D\u0435 \u043C\u0435\u043D\u044F\u0435\u0442.",
              "- \u0415\u0441\u043B\u0438 \u043E\u0442\u043A\u043B\u044E\u0447\u0438\u0442\u044C \u0432\u0437\u044F\u0442\u0438\u0435 \u043D\u0430\u0437\u0430\u0434 \u0434\u043B\u044F \u043F\u0440\u043E\u0441\u0442\u043E\u0439 \u0448\u0430\u0448\u043A\u0438, \u043E\u043D\u0430 \u0441\u043C\u043E\u0436\u0435\u0442 \u0431\u0438\u0442\u044C \u0442\u043E\u043B\u044C\u043A\u043E \u0432\u043F\u0435\u0440\u0451\u0434.",
              "- \u0415\u0441\u043B\u0438 \u043E\u0442\u043A\u043B\u044E\u0447\u0438\u0442\u044C \u0434\u0430\u043B\u044C\u043D\u0438\u0435 \u0445\u043E\u0434\u044B \u0434\u0430\u043C\u043A\u0438, \u043E\u043D\u0430 \u0431\u0443\u0434\u0435\u0442 \u0445\u043E\u0434\u0438\u0442\u044C \u043D\u0430 \u043E\u0434\u043D\u0443 \u043A\u043B\u0435\u0442\u043A\u0443 \u043F\u043E \u0434\u0438\u0430\u0433\u043E\u043D\u0430\u043B\u0438 \u0438 \u0431\u0440\u0430\u0442\u044C \u0442\u043E\u043B\u044C\u043A\u043E \u0441\u043E\u0441\u0435\u0434\u043D\u044E\u044E \u0448\u0430\u0448\u043A\u0443 \u043F\u0440\u044B\u0436\u043A\u043E\u043C \u0447\u0435\u0440\u0435\u0437 \u043D\u0435\u0451.",
              "- \u0411\u0435\u0437 \u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u043E\u0433\u043E \u0432\u0437\u044F\u0442\u0438\u044F \u0440\u0430\u0437\u0440\u0435\u0448\u0451\u043D \u043E\u0431\u044B\u0447\u043D\u044B\u0439 \u0445\u043E\u0434, \u0434\u0430\u0436\u0435 \u043A\u043E\u0433\u0434\u0430 \u043C\u043E\u0436\u043D\u043E \u043A\u043E\u0433\u043E-\u0442\u043E \u043F\u043E\u0431\u0438\u0442\u044C.",
              "- \u0415\u0441\u043B\u0438 \u043E\u0442\u043A\u043B\u044E\u0447\u0438\u0442\u044C \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0435\u043D\u0438\u0435 \u0432\u0437\u044F\u0442\u0438\u0439, \u0445\u043E\u0434 \u0437\u0430\u043A\u043E\u043D\u0447\u0438\u0442\u0441\u044F \u043F\u043E\u0441\u043B\u0435 \u043F\u0435\u0440\u0432\u043E\u0433\u043E \u043F\u0440\u044B\u0436\u043A\u0430.",
              "- \u0411\u0435\u0437 \u0442\u0440\u0435\u0431\u043E\u0432\u0430\u043D\u0438\u044F \u0441\u0430\u043C\u043E\u0433\u043E \u0434\u043B\u0438\u043D\u043D\u043E\u0433\u043E \u0432\u0437\u044F\u0442\u0438\u044F \u043C\u043E\u0436\u043D\u043E \u0432\u044B\u0431\u0438\u0440\u0430\u0442\u044C \u043B\u044E\u0431\u0443\u044E \u0434\u043E\u043F\u0443\u0441\u0442\u0438\u043C\u0443\u044E \u0446\u0435\u043F\u043E\u0447\u043A\u0443. \u0422\u0440\u0435\u0431\u043E\u0432\u0430\u043D\u0438\u0435 \u043C\u0430\u043A\u0441\u0438\u043C\u0430\u043B\u044C\u043D\u043E\u0433\u043E \u0447\u0438\u0441\u043B\u0430 \u0432\u0437\u044F\u0442\u0438\u0439 \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u043E \u043B\u0438\u0448\u044C \u0432\u043C\u0435\u0441\u0442\u0435 \u0441 \u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u044B\u043C \u0432\u0437\u044F\u0442\u0438\u0435\u043C \u0438 \u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u044B\u043C \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0435\u043D\u0438\u0435\u043C \u0446\u0435\u043F\u043E\u0447\u043A\u0438.",
              "- \u041F\u0440\u043E\u0441\u0442\u044B\u043C \u0448\u0430\u0448\u043A\u0430\u043C \u043C\u043E\u0436\u043D\u043E \u0440\u0430\u0437\u0440\u0435\u0448\u0438\u0442\u044C \u043E\u0431\u044B\u0447\u043D\u044B\u0439 \u0445\u043E\u0434 \u043D\u0430\u0437\u0430\u0434 \u043D\u0430 \u043E\u0434\u043D\u0443 \u0441\u0432\u043E\u0431\u043E\u0434\u043D\u0443\u044E \u043A\u043B\u0435\u0442\u043A\u0443 \u043F\u043E \u0434\u0438\u0430\u0433\u043E\u043D\u0430\u043B\u0438. \u0412 \u043E\u0441\u043D\u043E\u0432\u043D\u043E\u0439 \u0438\u0433\u0440\u0435 \u043D\u0430\u0437\u0430\u0434 \u043E\u043D\u0438 \u0434\u0432\u0438\u0433\u0430\u044E\u0442\u0441\u044F \u0442\u043E\u043B\u044C\u043A\u043E \u043F\u0440\u0438 \u0432\u0437\u044F\u0442\u0438\u0438.",
              "- \u041F\u0440\u0438\u043E\u0440\u0438\u0442\u0435\u0442 \u0434\u0430\u043C\u043A\u0438 \u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u0435\u0451, \u0435\u0441\u043B\u0438 \u0434\u0430\u043C\u043A\u0430 \u0438 \u043F\u0440\u043E\u0441\u0442\u0430\u044F \u0448\u0430\u0448\u043A\u0430 \u043C\u043E\u0433\u0443\u0442 \u0432\u044B\u043F\u043E\u043B\u043D\u0438\u0442\u044C \u043E\u0434\u0438\u043D\u0430\u043A\u043E\u0432\u043E \u0434\u043B\u0438\u043D\u043D\u044B\u0435 \u043C\u0430\u043A\u0441\u0438\u043C\u0430\u043B\u044C\u043D\u044B\u0435 \u0432\u0437\u044F\u0442\u0438\u044F. \u0414\u043B\u044F \u044D\u0442\u043E\u0433\u043E \u0432\u0430\u0440\u0438\u0430\u043D\u0442\u0430 \u043D\u0435\u043E\u0431\u0445\u043E\u0434\u0438\u043C\u043E \u043F\u0440\u0430\u0432\u0438\u043B\u043E \u0441\u0430\u043C\u043E\u0433\u043E \u0434\u043B\u0438\u043D\u043D\u043E\u0433\u043E \u0432\u0437\u044F\u0442\u0438\u044F. \u041E\u0431\u044B\u0447\u043D\u043E \u043F\u0440\u0438\u043E\u0440\u0438\u0442\u0435\u0442 \u0432\u044B\u043A\u043B\u044E\u0447\u0435\u043D.",
              "- \u041F\u0440\u0438 \u043D\u0435\u043C\u0435\u0434\u043B\u0435\u043D\u043D\u043E\u043C \u043F\u0440\u0435\u0432\u0440\u0430\u0449\u0435\u043D\u0438\u0438 \u0448\u0430\u0448\u043A\u0430 \u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u0441\u044F \u0434\u0430\u043C\u043A\u043E\u0439, \u043A\u0430\u043A \u0442\u043E\u043B\u044C\u043A\u043E \u0434\u043E\u0441\u0442\u0438\u0433\u0430\u0435\u0442 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0435\u0433\u043E \u0440\u044F\u0434\u0430 \u0432\u043E \u0432\u0440\u0435\u043C\u044F \u0432\u0437\u044F\u0442\u0438\u044F. \u041E\u0441\u0442\u0430\u0432\u0448\u0438\u0435\u0441\u044F \u043F\u0440\u044B\u0436\u043A\u0438 \u043E\u043D\u0430 \u0434\u0435\u043B\u0430\u0435\u0442 \u0443\u0436\u0435 \u043F\u043E \u043F\u0440\u0430\u0432\u0438\u043B\u0430\u043C \u0434\u0430\u043C\u043A\u0438.",
              "- \u041C\u043E\u0436\u043D\u043E \u043E\u0442\u043A\u043B\u044E\u0447\u0438\u0442\u044C \u0441\u043E\u0445\u0440\u0430\u043D\u0435\u043D\u0438\u0435 \u0432\u0437\u044F\u0442\u044B\u0445 \u0448\u0430\u0448\u0435\u043A \u043D\u0430 \u0434\u043E\u0441\u043A\u0435 \u0434\u043E \u043A\u043E\u043D\u0446\u0430 \u0445\u043E\u0434\u0430. \u0422\u043E\u0433\u0434\u0430 \u043A\u0430\u0436\u0434\u0430\u044F \u0441\u043D\u0438\u043C\u0430\u0435\u0442\u0441\u044F \u0441\u0440\u0430\u0437\u0443 \u043F\u043E\u0441\u043B\u0435 \u043F\u0440\u044B\u0436\u043A\u0430 \u0438 \u043C\u043E\u0436\u0435\u0442 \u043E\u0442\u043A\u0440\u044B\u0442\u044C \u043F\u0443\u0442\u044C \u0434\u043B\u044F \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0433\u043E \u0432\u0437\u044F\u0442\u0438\u044F."),
            rule_section(:controls, "\u041A\u043B\u0430\u0432\u0438\u0448\u0438 \u0443\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u044F",
              "\u0421\u0442\u0440\u0435\u043B\u043A\u0438: \u043F\u0440\u043E\u0441\u043C\u043E\u0442\u0440\u0435\u0442\u044C \u043A\u043B\u0435\u0442\u043A\u0438 \u0434\u043E\u0441\u043A\u0438.",
              "Enter: \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u0448\u0430\u0448\u043A\u0443 \u0438\u043B\u0438 \u0434\u0430\u043C\u043A\u0443, \u0437\u0430\u0442\u0435\u043C \u043A\u043B\u0435\u0442\u043A\u0443 \u043D\u0430\u0437\u043D\u0430\u0447\u0435\u043D\u0438\u044F; \u043F\u0440\u0438 \u043D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u0438\u0445 \u0432\u0437\u044F\u0442\u0438\u044F\u0445 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u044C \u043A\u0430\u0436\u0434\u044B\u0439 \u043F\u0440\u044B\u0436\u043E\u043A \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u043E.",
              "V: \u0443\u0437\u043D\u0430\u0442\u044C \u0434\u043E\u043F\u0443\u0441\u0442\u0438\u043C\u044B\u0435 \u0445\u043E\u0434\u044B \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u043E\u0439 \u0448\u0430\u0448\u043A\u0438 \u0438\u043B\u0438 \u0434\u0430\u043C\u043A\u0438.",
              "K: \u043F\u0435\u0440\u0435\u0439\u0442\u0438 \u043A \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0439 \u0441\u0432\u043E\u0435\u0439 \u0434\u0430\u043C\u043A\u0435.",
              "Shift+K: \u043F\u0435\u0440\u0435\u0439\u0442\u0438 \u043A \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0439 \u0434\u0430\u043C\u043A\u0435 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430.",
              "C: \u0443\u0437\u043D\u0430\u0442\u044C \u0446\u0432\u0435\u0442\u0430 \u0438\u0433\u0440\u043E\u043A\u043E\u0432.",
              "S: \u0443\u0437\u043D\u0430\u0442\u044C \u0447\u0438\u0441\u043B\u043E \u043E\u0441\u0442\u0430\u0432\u0448\u0438\u0445\u0441\u044F \u0448\u0430\u0448\u0435\u043A \u0438 \u0434\u0430\u043C\u043E\u043A \u0443 \u043E\u0431\u043E\u0438\u0445 \u0438\u0433\u0440\u043E\u043A\u043E\u0432.",
              "Ctrl+H: \u043F\u0435\u0440\u0435\u043A\u043B\u044E\u0447\u0438\u0442\u044C\u0441\u044F \u043C\u0435\u0436\u0434\u0443 \u043D\u043E\u043C\u0435\u0440\u0430\u043C\u0438 \u043F\u043E\u043B\u0435\u0439 \u0438 \u0448\u0430\u0445\u043C\u0430\u0442\u043D\u044B\u043C\u0438 \u043A\u043E\u043E\u0440\u0434\u0438\u043D\u0430\u0442\u0430\u043C\u0438.",
              "Ctrl+Shift+H: \u0440\u0430\u0437\u0432\u0435\u0440\u043D\u0443\u0442\u044C \u0434\u043E\u0441\u043A\u0443.",
              "T: \u0443\u0437\u043D\u0430\u0442\u044C, \u0447\u0435\u0439 \u0441\u0435\u0439\u0447\u0430\u0441 \u0445\u043E\u0434.")
          ]
